import json, hashlib, copy, re
from pathlib import Path
ROOT=Path(__file__).resolve().parent
P=json.loads((ROOT/'packet.json').read_text())
E={e['source_id']:e for e in P['entries']}; T={k:v['text'] for k,v in E.items()}
U={}; R=[]; N={}; seq=[]
def span(s,q,start=0):
    i=T[s].find(q,start)
    if i<0: raise ValueError((s,q))
    return {'start':i,'end':i+len(q),'quote':q}
def ev(s,q,start=0):return {'source_id':s,'span':span(s,q,start)}
def evidence(*pairs):return [ev(*p) for p in pairs]
def add(k,s,q,cs=(),role='statement',grammar='regulative',speech='proposed',force='recommendation',itype='undetermined',standing='text_only',scope='case_specific',parse='literal',target='operational',observed='operational',why='',alt='',unc='',conf='plausible',quotation='none',markup='plain',flags=None,levels=None):
    sp=span(s,q)
    u={'unit_id':'B-'+k,'source_id':s,'span':sp,'parent_unit_id':None,'record_role':role,'grammar':grammar if role=='statement' else 'not_institutional','speech_act':speech,'scope':scope,'parse_mode':parse,'deontic_force':force if role=='statement' else 'nondeontic','components':[], 'institution':{'type':itype if role=='statement' else 'not_applicable','standing':standing if role=='statement' else 'not_applicable','dispute_present':False,'rationale':why or ('A bounded contribution-review proposal; no supplied authority turns the request itself into a rule.' if role=='statement' else 'Context endpoint, not an additional independently extracted institutional proposition.'),'evidence':[{'source_id':s,'span':sp}],'recognition':[],'authority_evidence':[]},'statement_target_level':target if role=='statement' else 'not_applicable','observed_action_level':'not_applicable' if role=='container' else observed,'level_rationale':('The focal activity is review, editing, or coordination within a contribution episode; no network adoption is inferred.' if target=='operational' else 'The focal activity is the stated institutional arrangement, not the technical vocabulary alone.'),'complexity_flags':flags or ['none'],'alternative_interpretation':alt,'confidence':conf,'uncertainty_reason':unc,'level_alternatives':levels or [],'presentation':{'quotation':quotation,'markup':markup,'rationale':'Presentation follows this supplied occurrence; later statuses are coded separately.'},'disposition_events':[]}
    U[k]=u
    for symbol,quote in cs: cp(k,symbol,quote)
    return u
def cp(k,symbol,q,text=None,basis='explicit',source=None,note='',occurrence=None):
    u=U[k];s=source or u['source_id']
    def validpos(i):
        if i<0:return False
        j=i+len(q);word=lambda c:c.isalnum() or c=='_'
        left=i>0 and word(q[0]) and (word(T[s][i-1]) or T[s][i-1]=='-')
        right=j<len(T[s]) and word(q[-1]) and (word(T[s][j]) or T[s][j]=='-')
        return not (left or right)
    positions=[m.start() for m in re.finditer(re.escape(q),T[s]) if validpos(m.start())]
    local=next((i for i in positions if s==u['source_id'] and u['span']['start']<=i and i+len(q)<=u['span']['end']),-1)
    chosen=local if local>=0 else next(iter(positions),-1)
    if chosen<0: raise ValueError(('component not found',k,symbol,q))
    e=ev(s,q,chosen)
    if occurrence is None:occurrence='semantic_inference' if basis!='explicit' else ('local' if local>=0 else 'context_reference')
    if local<0 and not note:raise ValueError(('outside note missing',k,symbol,q))
    if u['parse_mode']=='pragmatic' and basis=='explicit' and symbol in ['A','Bdir','Bind'] and not note: note='This argument remains the explicitly expressed actor or target of the stated action; pragmatic coding concerns the requested force or reconstructed action, not an invented referent.'
    u['components'].append({'symbol':symbol,'text':text or q,'basis':basis,'evidence':[e],'inference_note':note,'occurrence_role':occurrence})
    return u['components'][-1]
def infer(k,sym,text,q,source=None,note='',role='semantic_inference',basis='context_inferred'):
    return cp(k,sym,q,text,basis,source,note or 'Reconstructs the action or argument role from this utterance; the reconstructed expression is not a verbatim institutional command.',role)
def context(k,s,q,speech='reported_action',quotation='none',markup='plain',why=''):
    return add(k,s,q,role='context',speech=speech,quotation=quotation,markup=markup,why=why,conf='clear')
def rel(a,b,typ,es,basis='context_inferred',why='',logic='not_applicable'):
    R.append({'from_unit_id':U[a]['unit_id'],'to_unit_id':U[b]['unit_id'],'type':typ,'basis':basis,'rationale':why,'evidence':es,'logic_scope':logic})
def rec(k,kind,target,es,why,basis='context_inferred'):
    U[k]['institution']['recognition'].append({'kind':kind,'target':target,'evidence':es,'rationale':why,'basis':basis})
def disp(k,kind,target,es,why,basis='context_inferred'):
    U[k]['disposition_events'].append({'kind':kind,'target':target,'basis':basis,'evidence':es,'rationale':why})
def quote(k,s,q,orig,origq=None):
    add(k,s,q,role='quotation',speech='asserted',quotation='repeated',conf='clear')
    rel(k,orig,'quotes',evidence((s,q),(U[orig]['source_id'],origq or U[orig]['span']['quote'])),'explicit','Repeated occurrence linked to the supplied original; this quotation is not an independent endorsement.')
def note(s,reason,missing='',alternatives=''):
    N[s]={'source_id':s,'reasoning':reason,'missing_context':missing,'consequential_alternatives':alternatives}
def disposition(k,pr,merged):
    s='M'+str(pr); kind='recorded_merged' if merged else 'recorded_closed_unmerged'
    disp(k,kind,'broader_proposal',evidence((s,T[s])),'Repository metadata establishes the disposition of the broader PR, not acceptance or exact implementation of every proposition. Closure without merger is not automatically rejection.','explicit')

# 32359-115: institutional remit, weighting, absence of duty, and anti-spam expectation.
s='32359-115'
add('115-remit',s,'this is a pull request open for code review, not a per-username voting forum.', [('E','this'),('F','is'),('P','a pull request open for code review, not a per-username voting forum')],grammar='constitutive',speech='asserted',force='nondeontic',itype='constitutive_specification',why='The participant defines the local discussion remit and expressly excludes username voting. Supplied later contribution documentation supports the review arena but does not establish the April wording was a formally adopted rule.',alt='A reminder about this discussion could also function as an indirect request to stop voting-style comments.',conf='clear')
add('115-merit',s,'Reviews are weighted by the merit of their arguments, not the number of times they are posted.', [('Bdir','Reviews'),('I','weighted'),('Cex','by the merit of their arguments, not the number of times they are posted')],speech='asserted',force='nondeontic',itype='norm_candidate',why='An asserted review-evaluation expectation rather than a vote count. The exact weighting practice is not observed.',alt='A constitutive account of how review weight is assigned preserves the same meaning. The later documentation permits merit weighting rather than proving every review was actually weighted this way.')
U['115-merit']['institution']['evidence']+=evidence(('D_CONTRIB','Project maintainers reserve the right to weigh the opinions of peer reviewers\nusing common sense judgement and may also weigh based on merit.'))
add('115-repeat',s,"if your point has already been made here or on #28130, you don't need to post it again.", [('Cac','if your point has already been made here or on #28130'),('A','you'),('D',"don't need to"),('I','post'),('Bdir','it'),('Cex','again')],speech='asserted',force='no_obligation',itype='norm_candidate',why='The negative modal denies a need to repeat an already expressed point; it does not by itself prohibit repetition.',alt='The surrounding anti-spam reminder makes non-repetition advisable, but the lexical statement is no obligation, not a prohibition.',conf='clear')
add('115-spam',s,'There is no reason to leave unsubstantiated or repeat acks/nacks other than to spam the people subscribed to this repo.',parse='pragmatic',itype='norm_candidate',why='The criticism pragmatically discourages unsubstantiated and repeated review labels. It is an accountability expectation, not an observed sanction.',alt='Literal reading: a claim about the reason for such comments rather than a separate instruction.',unc='The imperative force is inferred from the reminder and evaluative wording.')
infer('115-spam','I','avoid leaving','There is no reason to leave'); cp('115-spam','Bdir','unsubstantiated or repeat acks/nacks');
U['115-spam']['institution']['evidence']+=evidence(('D_MOD','Comments should contribute new information.'))
note(s,'Four propositions preserve remit, merit weighting, a denial of any need to repeat a point, and an inferred anti-spam expectation. No particular person is assigned reviewer-weighting authority from their username.','No direct response or instance of comment removal is supplied for this reminder. The contribution document snapshot is later than the comment.','The remit and merit claims can be constitutive or regulative descriptions. No-obligation must not be silently converted into a prohibition; anti-spam force is pragmatic.')

